import { Component } from 'react'
import PropTypes from 'prop-types'
import { Button } from '../../../../../components'
import { VerificationEmailStyle, CustomTextStyle } from './index.style'
import { VERIFY_EMAIL_SUCCESS, VERIFIED_EMAIL_SVG } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { AgentColorPallette } from '../../../../../configs/colorPallete'

class EmailVerificationSuccess extends Component {
  static propTypes = {
    history: PropTypes.object,
    email: PropTypes.string
  }

  handleToProfile = () => {
    this.props.history.replace('/profile')
  }

  render () {
    const { email } = this.props
    if (!email) {
      // if this url not exist then move to login page
      this.props.history.replace('/login')
    }
    return (
      <VerificationEmailStyle bgUrl={VERIFY_EMAIL_SUCCESS}>
        <div className='verify-icon'>
          <img src={VERIFIED_EMAIL_SVG} alt='' />
        </div>
        <CustomTextStyle
          fontSize='20px'
          paddingTop='50px'
          marginBottom='20px'
          fontWeight='800'
          textAlign='center'
          className='verify-content-width'
        >
          {LANG_STRINGS.emailVerificationSuccessful}
        </CustomTextStyle>
        <CustomTextStyle fontSize='16px' textAlign='center' lineHeight={1.5}>
          {LANG_STRINGS.verifyEmailFirst}
        </CustomTextStyle>
        <CustomTextStyle
          fontWeight='800'
          fontSize='16px'
          textAlign='center'
          fontColor={AgentColorPallette.primary}
          lineHeight={1.5}
        >
          {email}
        </CustomTextStyle>
        <CustomTextStyle
          fontSize='16px'
          textAlign='center'
          lineHeight={1.5}
          className='verify-content-width'
        >
          {LANG_STRINGS.verifyEmailSecond}
        </CustomTextStyle>
        <Button className='go-to-profile' onClick={this.handleToProfile}>
          {LANG_STRINGS.towardsYourProfile}
        </Button>
      </VerificationEmailStyle>
    )
  }
}

export default EmailVerificationSuccess
