import { PureComponent } from 'react'
import { PageNotFoundStyle } from './index.style'
import { CustomText } from '..'
import { LANG_STRINGS } from '../../lang'
import { AgentColorPallette } from '../../configs/colorPallete'
import Button from '../Button'
import { SAD_SMILE } from '../../images'
import MitraContactFooter from '../MitraContactFooter'

class PageNotFound extends PureComponent {
  handleBtnClick = () => {
    this.props.history.replace('/login')
  }

  render () {
    return (
      <PageNotFoundStyle>
        <div>
          <img src={SAD_SMILE} alt='' />
        </div>
        <CustomText
          size='24px'
          weight={800}
          textAlign='center'
          color={AgentColorPallette.errorDark}
        >
          {LANG_STRINGS.pageNotFound}
        </CustomText>
        <Button onClick={this.handleBtnClick} className='page-btn'>
          {LANG_STRINGS.loginBtnText}
        </Button>
        <MitraContactFooter />
      </PageNotFoundStyle>
    )
  }
}

export default PageNotFound
