import { Component } from 'react'
import { connect } from 'react-redux'
import { Container } from '../../../components'
import EmailVerificationSuccess from './components/EmailVerificationSuccess'
import EmailVerificationFailed from './components/EmailVerificationFailed'
import verificationAction from '../../../redux/verification/actions'
import PageNotFound from '../../../components/PageNotFound'

const { validateUserEmail, resetVerificationStore } = verificationAction

class EmailVerificationPage extends Component {
  componentDidMount () {
    const { agentCode, token } = this.props.match.params
    this.props.validateUserEmail({
      agentCode,
      token
    })
  }

  componentWillReceiveProps (nextProps) {
    const { emailStatusDataMsg } = nextProps

    if (emailStatusDataMsg && emailStatusDataMsg !== 'success') {
      // if there are then redirect the user to login page
      // this.props.history.replace('/login')
      this.props.resetVerificationStore(['emailStatusDataMsg'])
    }
  }

  render () {
    const { history, emailLoading, emailStatusData, emailStatusDataMsg, emailError } = this.props
    return (
      <>
        <Container loader={emailLoading} mitraHeader hideBottomTabs>
          {
            (emailStatusData && emailStatusData.is_verified)
              ? (<EmailVerificationSuccess history={history} email={emailStatusData.receiver} />)
              : (emailStatusDataMsg === 'success') ? (<EmailVerificationFailed history={history} />)
                : (emailError && <PageNotFound history={history} />)
          }
        </Container>
      </>
    )
  }
}

export default connect(
  state => ({
    emailStatusData: state.Verification.emailStatusData,
    emailLoading: state.Loading.VALIDATE_EMAIL,
    emailError: state.Error.VALIDATE_EMAIL,
    emailStatusDataMsg: state.Verification.emailStatusDataMsg
  }),
  {
    validateUserEmail,
    resetVerificationStore
  }
)(EmailVerificationPage)
