import { Component } from 'react'
import PropTypes from 'prop-types'
import { Button } from '../../../../../components'
import { VerificationEmailStyle, CustomTextStyle } from '../EmailVerificationSuccess/index.style'
import { VERIFY_EMAIL_FAILED, VERIFIED_EMAIL_TIME_PASSED } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import MitraContactFooter from '../../../../../components/MitraContactFooter'

class EmailVerificationFailed extends Component {
  static propTypes = {
    history: PropTypes.object
  }

  handleToVerificationPage = () => {
    this.props.history.replace('/my-profile')
  }

  render () {
    return (
      <VerificationEmailStyle bgUrl={VERIFY_EMAIL_FAILED}>
        <div className='verify-icon'>
          <img src={VERIFIED_EMAIL_TIME_PASSED} alt='' />
        </div>
        <CustomTextStyle
          fontSize='20px'
          paddingTop='50px'
          marginBottom='20px'
          fontWeight='800'
          textAlign='center'
          className='verify-content-width'
        >
          {LANG_STRINGS.verificationLinkExpired}
        </CustomTextStyle>
        <CustomTextStyle fontSize='16px' textAlign='center' lineHeight={1.5}>
          {LANG_STRINGS.linkNotUsedContent}
        </CustomTextStyle>
        <Button className='go-to-verification' onClick={this.handleToVerificationPage}>
          {LANG_STRINGS.goVerificationPage}
        </Button>
        <MitraContactFooter />
      </VerificationEmailStyle>
    )
  }
}

export default EmailVerificationFailed
